'use client';

import { useMemo, useState } from 'react';
import Lightbox from './Lightbox';

/** category -> [url, width, height][]  (generated by scripts/build-gallery.mjs from the photo folders) */
export type GalleryData = Record<string, [string, number, number][]>;

const LABELS: { key: string; label: string }[] = [
  { key: 'proposal', label: 'Proposal' },
  { key: 'groom', label: 'Groom' },
  { key: 'bride', label: 'Bride' },
  { key: 'family', label: 'Family' },
  { key: 'bridal', label: 'Bridal Team' },
  { key: 'venue', label: 'Event Location' },
  { key: 'more', label: 'More' },
];

export default function Gallery({ data }: { data: GalleryData }) {
  const tabs = useMemo(() => {
    const cats = LABELS.filter((t) => (data[t.key]?.length ?? 0) > 0);
    const all = cats.flatMap((t) => data[t.key]);
    return [{ key: 'all', label: 'All photos', photos: all }, ...cats.map((t) => ({ ...t, photos: data[t.key] }))];
  }, [data]);

  const [tab, setTab] = useState('all');
  const [open, setOpen] = useState<number | null>(null);
  const current = tabs.find((t) => t.key === tab) ?? tabs[0];
  const photos = current.photos;

  return (
    <>
      <div className="tabs" role="tablist" aria-label="Gallery categories">
        {tabs.map((t) => (
          <button key={t.key} role="tab" aria-selected={tab === t.key} className={tab === t.key ? 'on' : ''} onClick={() => { setTab(t.key); setOpen(null); }}>
            {t.label} <small>{t.photos.length}</small>
          </button>
        ))}
      </div>

      <div className="masonry" key={tab}>
        {photos.map(([url, w, h], i) => (
          <button key={url} className="m-item" style={{ aspectRatio: `${w} / ${h}`, animationDelay: `${Math.min(i, 14) * 60}ms` }} onClick={() => setOpen(i)} aria-label={`Open photo ${i + 1} of ${photos.length}`}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={url} alt={`${current.label}, photo ${i + 1}`} loading="lazy" decoding="async" width={w} height={h} />
          </button>
        ))}
      </div>

      {open !== null && photos[open] && (
        <Lightbox images={photos.map(([u]) => u)} index={open} onIndex={setOpen} onClose={() => setOpen(null)} title={current.label} />
      )}
    </>
  );
}
